          "model_answer": "A primary reason British men volunteered in huge numbers in autumn 1914 was powerful patriotic enthusiasm and anti-German propaganda. Lord Kitchener’s famous recruitment poster and newspaper reports of German atrocities in neutral Belgium convinced men it was their moral duty to defend King and country.<br><br>Furthermore, social pressure and 'Pals Battalions' drove mass enlistment. The War Office encouraged friends, sports teams, and factory workmates to join up together with the promise of serving side by side. Fearing public shame or being handed a white feather for cowardice, over 750,000 men enlisted by the end of September.",
          "topic": "Extended Historical Writing • Causal Explanation (2–3 Paragraphs • 15 mins)"
