      "vocab_cloze_text": "In August 1914, Britain entered the conflict with a small professional army known as the [British Expeditionary Force]. To meet the demand for millions of soldiers, War Secretary [Lord Kitchener] launched an unprecedented recruitment drive. Enthusiastic [Jingoism] swept the nation as entire towns formed [Pals Battalions] to fight side-by-side. Behind the patriotic fanfare, however, civilian groups weaponized social shame by handing out the [White Feather] to men out of uniform, while working-class recruits often volunteered out of economic [Pragmatism] to escape grinding factory poverty.",
