          "viewing_task": "<ol><li><strong>[00:40] Quick Check:</strong> Which prominent British Secretary of State for War was depicted pointing his gloved finger on the iconic September 1914 recruitment poster \"Your Country Needs You\"?</li><li><strong>[01:50] Hinge Question:</strong> Why were hundreds of thousands of young British men so eager to volunteer for military service in August and September 1914 before conscription was introduced?</li></ol>",
          "model_answer": "<ol><li><strong>Quick Check:</strong> Field Marshal Lord Horatio Kitchener.</li><li><strong>Hinge Question:</strong> A powerful mixture of romantic patriotism, social pressure (such as women presenting white feathers to young men in civilian clothes), fear of missing out on the \"great adventure\" of their generation, and the widespread belief that the war would be \"over by Christmas.\" For impoverished working-class youths, the army also promised regular hot meals, boots, and better pay than factory labor.</li></ol>"
