          "viewing_task": "<ol><li><strong>[00:40] Recall:</strong> What lies about age did underage British teenagers routinely tell recruiting sergeants to enlist in 1914?</li><li><strong>[01:15] Explain:</strong> Explain how peer pressure, white feathers, and the desire to \"not miss the big adventure\" before Christmas compelled over 750,000 men to volunteer in the war's first two months.</li><li><strong>[02:00] Challenge:</strong> Evaluate why the destruction of the Pals Battalions on the first day of the Somme (1 July 1916) permanently traumatized communities across northern England.</li></ol>",
          "model_answer": "<ol><li><strong>Recall:</strong> Underage boys claimed to be 19 years old (the legal minimum for overseas service), often encouraged by recruiters earning bonuses.</li><li><strong>Explain:</strong> The intense moral pressure of posters (\"What did YOU do in the Great War, Daddy?\"), women handing white feathers to men in civilian clothes, and the universal belief that the war would be short and victorious convinced young men that enlisting was the ultimate mark of manhood and civic duty.</li><li><strong>Challenge:</strong> Because men from the same factory, cricket club, or church enrolled together in Pals Battalions, when units charged machine guns at Serre and Thiepval on 1 July 1916, hundreds of neighbors and brothers died side by side in minutes. Entire towns were plunged into immediate communal mourning, destroying local civic identity and ending voluntary recruitment forever.</li></ol>"
