          "viewing_task": "<ol><li><strong>[03:30] Recall:</strong> Why do Will and his village football teammates decide to enlist together at the local recruiting fair in 1914?</li><li><strong>[16:00] Explain:</strong> What happens in No Man’s Land on Christmas Day 1914, and why did senior officers try to prevent fraternisation afterwards?</li><li><strong>[24:30] Hinge Question:</strong> How does <em>War Game</em> illustrate both the powerful recruitment appeal of Pals Battalions in 1914 and the devastating community tragedy when a single Pals unit attacked together?</li></ol>",
