        "rows": 3,
        "model_answer": "Enlistment in 1914 was driven by a powerful balance of negative push factors and positive pull factors. Push factors included the intense fear of social disgrace from white feathers, emotional guilt from posters like \"Women of Britain Say GO!\", and the grinding misery of factory poverty. In contrast, pull factors included the intoxicating camaraderie of joining Pals Battalions with friends, moral conviction to avenge Belgium, and the tangible economic benefit of guaranteed pay, hot food, and warm uniforms."
