          "caption": "Field Marshal Lord Kitchener, Secretary of State for War, speaking at the Guildhall in London, 4 September 1914.",
          "citation": "The Times Archive / Parliamentary Debates, Official Report (Hansard), Sept 1914.",
          "context": "Appointed Secretary of State for War on 5 August 1914, Kitchener broke with military convention by forecasting a war lasting at least three years, requiring an army of millions rather than Britain’s existing 120,000-strong expeditionary force.",
          "question_badge": "Author’s Purpose",
