      "vocab_cloze_text": "Following the Battle of the Marne in 1914, both armies dug defensive trenches, creating an unbroken 400-mile [Stalemate]. Attacking troops faced devastating machine guns and massed [Artillery] across the shell-torn expanse of [No Man's Land]. In the damp trenches, men lived in filth, suffering agonizing fungal rot called [Trench Foot] and debilitating psychological trauma known as [Shell Shock]. Believing in a war of [Attrition], British Commander-in-Chief [Field Marshal Douglas Haig] sought to bleed the enemy dry, eventually perfecting the [Creeping Barrage] to coordinate infantry with advancing curtains of artillery.",
