          "text": "<p class=\"prose-p\"><span class=\"para-ref\">[2.1]</span> In autumn 1914, fluid mobile warfare ended as rival armies attempted to outflank each other in the Race to the Sea. When both sides reached the English Channel coast, open movement became impossible against modern rapid-firing industrial weaponry.</p><p class=\"prose-p\">Lethal artillery shrapnel and deadly machine guns sweeping open fields forced infantry into digging in to survive. Soldiers carved protective earthen trenches, establishing an unbroken 400-mile fortified front line stretching from the North Sea coast to the Swiss border.</p>",
