          "paras": [
            "Frontline defenses evolved into an intricate three-tier defensive system: the frontline fire trench, the support trench (several hundred yards behind), and the reserve trench, connected by communication trenches.",
            "Trenches were constructed in a zig-zag pattern so that an explosive shell burst or infiltrating enemy raider could not clear an entire trench line.",
            "Ahead of the frontline lay No Man’s Land, guarded by thick belts of coiled barbed wire designed to channel attackers into pre-sighted machine-gun kill zones. Deep underground, reinforced subterranean concrete dugouts sheltered defending troops from artillery bombardments."
          ],
          "text": "<p class=\"prose-p\"><span class=\"para-ref\">[2.2]</span> Frontline trenches evolved into elaborate three-tier defensive networks comprising front, support, and reserve positions. Engineers designed distinct zig-zag trench lines with sandbagged traverses to stop enemy invaders firing directly down straight alleys and contain explosive blast damage.</p><p class=\"prose-p\">In front of the parapets, soldiers strung dense barbed wire traps hundreds of yards deep to funnel attacking infantry into machine-gun kill zones. Behind the lines, deep concrete dugouts thirty feet underground provided shelter from continuous artillery bombardments.</p>",
