        "source_context": {
          "Source A": "The British war effort relied on the mobilization of over 3 million troops from across the British Empire, including 1.5 million from the Indian subcontinent, and hundreds of thousands from Canada, Australia, New Zealand, the Caribbean, and Africa. **Hinge Question:** Why did the British government use allegorical imagery of an 'Old Lion' and 'Young Lions' rather than portraying the authentic ethnic diversity of imperial subjects who actually fought?",
          "Source B": "On 31 October 1914 at Hollebeke, Belgium, Khudadad Khan’s machine-gun team was overrun during the First Battle of Ypres. Though wounded and with all comrades killed, he kept his gun firing, delaying the German advance until reinforcements arrived. King George V personally pinned the Victoria Cross to his chest. **Hinge Question:** Why was King George V eager to award the highest military honour to an Indian sepoy in 1914, and how did this contradict Britain's colonial racial hierarchy?",
          "Source C": "The 1914 Manual of Military Law strictly barred any person not of 'pure European descent' from holding an officer's commission. Walter Tull’s exceptional courage and leadership led his commanding officers to break the law and commission him. He was killed in action leading his men at the Second Battle of the Somme in March 1918. **Hinge Question:** How did Walter Tull's promotion to officer rank challenge the British Army’s explicit racial rules, and why did the War Office refuse to officially award him the Military Cross recommended by his superiors?",
          "Source D": "Over 140,000 Chinese men were recruited under strict military contracts to maintain the British and French armies' supply chains. They dug trenches, handled heavy toxic explosives, and cleared unexploded ordnance under fire, yet their critical contribution was virtually erased from European commemorative monuments. **Hinge Question:** Why were the 140,000 men of the Chinese Labour Corps completely omitted from Allied victory parades and official national memorials after 1918?",
          "Source E": "Over 16,000 Caribbean men volunteered for the BWIR. Following the Armistice, while white troops were demobilized, BWIR soldiers were held in degrading conditions at Taranto, Italy, and forced to do heavy manual chores. The resulting strike led directly to the formation of the Caribbean League and early independence movements. **Hinge Question:** Why did the British military establishment treat volunteer soldiers from the Caribbean as manual labourers rather than combatants?"
        },
