          "heading": "Gallipoli, ANZAC Identity & The British West Indies Regiment",
          "content": "<p class=\"prose-p\"><span class=\"para-ref\">[3.3]</span> In April 1915, Allied forces launched an amphibious invasion of Gallipoli to knock the Ottoman Empire out of the war. Landing at dawn, Australian and New Zealand Army Corps (ANZAC) troops found themselves trapped below Anzac Cove steep cliffs under murderous fire.</p><p class=\"prose-p\">Entrenched Turkish defenders swept exposed ravines with lethal Ottoman machine guns, pinning Allied soldiers on rocky beaches. Eight months of bloody stalemate ended in total evacuation, yet the courage shown by dominion troops marked the permanent birth of ANZAC legend and national pride.</p>",
          "body": "<p class=\"prose-p\"><span class=\"para-ref\">[3.3]</span> In April 1915, Allied forces launched an amphibious invasion of Gallipoli to knock the Ottoman Empire out of the war. Landing at dawn, Australian and New Zealand Army Corps (ANZAC) troops found themselves trapped below Anzac Cove steep cliffs under murderous fire.</p><p class=\"prose-p\">Entrenched Turkish defenders swept exposed ravines with lethal Ottoman machine guns, pinning Allied soldiers on rocky beaches. Eight months of bloody stalemate ended in total evacuation, yet the courage shown by dominion troops marked the permanent birth of ANZAC legend and national pride.</p>"
