          "body": "<p class=\"prose-p\"><span class=\"para-ref\">[3.4]</span> Behind front lines, Allied armies depended on civilian logistics battalions to sustain industrial warfare. Over 140,000 Chinese labourers of the Chinese Labour Corps travelled halfway around the world to dig communication trenches, repair railway tracks, and clear deadly battlefields.</p><p class=\"prose-p\">These workers performed exhausting shifts unloading heavy shells and toxic chemical munitions under constant bombardment. Despite their indispensable contribution, imperial authorities subjected Chinese workers to guarded curfew camps, harsh corporal punishment, and strict racial segregation that barred contact with local French civilians.</p>",
