          "body": "<p class=\"prose-p\"><span class=\"para-ref\">[3.5]</span> Despite sacrificing millions of lives, colonial service was met with deliberate institutional prejudice after the war. In East Africa, over one million African porters died carrying military supplies, yet imperial authorities left no marked African graves across former colonial battlefields.</p><p class=\"prose-p\">Unlike white British soldiers who received individual headstones, fallen African and Asian labourers were buried in anonymous pits without names. Furthermore, non-white troops were excluded from the 1919 London Victory Parade erasure, denying colonial subjects equal recognition, pensions, and remembrance for decades.</p>",
