        "model_answer": "The wartime experience of British women was a profound paradox. On one hand, women achieved unprecedented liberation: earning substantial independent wages in engineering factories, breaking out of low-paid domestic service, and gaining social autonomy in public life. On the other hand, they endured ruthless exploitation: working grueling 12-hour shifts without chemical masks, suffering yellow skin and liver failure from TNT poisoning, facing lethal factory explosions, and being paid far less than men. Crucially, when the war ended in 1919, over 750,000 women were sacked and forced back into domestic work to restore jobs to returning male soldiers."
