        "source_context": {
          "Source A": "On 8 August 1918 at the Battle of Amiens, British, Canadian, and Australian forces launched a combined-arms offensive with 500 tanks, advancing eight miles in a single day. Ludendorff realized the German Army could no longer win and urged the Kaiser to seek peace. **Hinge Question:** Why did the sudden collapse of the German frontline on 8 August 1918 shatter the German High Command's belief that they could still negotiate from a position of strength?",
          "Source B": "Signed at 5:00 am on 11 November 1918 to take effect at the 11th hour of the 11th day, the Armistice stripped Germany of its heavy armaments and naval fleet, ensuring it could not resume the war while the peace treaty was drafted. **Hinge Question:** Why did Allied leaders insist that Germany surrender all heavy weapons and submarines in the Armistice before peace negotiations even began?",
          "Source C": "The Big Four met in Paris from January to June 1919 to reshape the world map following the collapse of four empires. Their clashing priorities—French revenge, British trade protection, and American idealism—produced a deeply flawed compromise. **Hinge Question:** Looking at the body language and differing national priorities of these four leaders, why was it virtually impossible for them to agree on a peaceful post-war settlement that satisfied everyone?",
          "Source D": "Under the treaty, Germany lost 13% of its European territory, all overseas colonies, its air force, and had its army capped at 100,000 men. Article 231 provided the legal foundation for reparations, later fixed at £6.6 billion. **Hinge Question:** Why did the combination of losing 13% of its land and signing the War Guilt Clause provoke greater outrage in Germany than any other aspect of the treaty?",
          "Source E": "Will Dyson produced what is universally regarded as the most uncannily accurate political prophecy in modern history. He recognized that by crushing Germany without destroying its demographic power, the treaty ensured a second catastrophic war exactly twenty years later, when the babies of 1919 reached fighting age ('1940 Class'). **Hinge Question:** Why was a British socialist cartoonist able to predict World War II in May 1919 with such astonishing chronological precision ('1940 Class'), while the world’s most powerful statesmen were blind to it?"
        },
