          "viewing_task": "<ol><li><strong>[00:30] Recall:</strong> At what exact hour and date did the Armistice end fighting on the Western Front?</li><li><strong>[01:10] Explain:</strong> Explain why celebrations on Armistice Day in November 1918 were mixed with grief and anger across Britain and France.</li><li><strong>[01:50] Challenge:</strong> Why was signing an armistice ceasefire far easier than agreeing a permanent peace treaty in Paris in 1919?</li></ol>",
          "model_answer": "<ol><li><strong>Recall:</strong> 11:00 a.m. on 11 November 1918.</li><li><strong>Explain:</strong> Nearly every family mourned dead or permanently maimed relatives while Spanish Flu was sweeping Europe, fueling public demands that Germany pay for the devastation.</li><li><strong>Challenge:</strong> An armistice merely stopped the shooting; at Paris, Britain, France, and the USA held clashing visions over vengeance, border security, empire, and self-determination.</li></ol>"
