          "duration": "18 mins 24 secs",
          "pathway": "Archival Documentary",
          "teacher_guidance": "BBC Two History File investigation into the 1919 Paris Peace Conference—exploring why Clemenceau, Wilson, and Lloyd George clashed at Versailles and debating whether the treaty was a vindictive failure or a difficult compromise. Recommended Watch Window: 01:00–12:00 • Lesson Phase: Historiographical Evaluation.",
          "viewing_task": "<ol><li><strong>[02:00] Recall:</strong> Why did French Prime Minister Georges Clemenceau demand far harsher security guarantees against Germany than US President Woodrow Wilson?</li><li><strong>[06:45] Explain:</strong> Explain which specific clauses of the Treaty of Versailles (Article 231, reparations, territorial losses, military caps) provoked the fiercest outrage inside Germany.</li><li><strong>[14:00] Hinge Question:</strong> Is it fair to blame the peacemakers of 1919 for causing the Second World War, given the devastation and public fury across Europe after 1918?</li></ol>",
          "model_answer": "<ol><li><strong>Recall:</strong> France shared a direct land border with Germany, had been invaded twice (1870 and 1914), and suffered catastrophic destruction across northern France, whereas America was protected by the Atlantic Ocean.</li><li><strong>Explain:</strong> Germans despised the dictated peace (<em>Diktat</em>), especially Article 231 (\"War Guilt\"), the £6.6 billion reparations bill, demilitarisation/100,000-man army limit, and losing land via the Polish Corridor while being denied self-determination.</li><li><strong>Hinge Question:</strong> Traditional critics argued Versailles was too harsh to conciliate Germany yet too lenient to crush its power permanently; modern historians emphasise that peacemakers faced impossible democratic pressures and devastated empires in 1919.</li></ol>"
