          "model_answer": "On the one hand, the Treaty of Versailles was exceptionally harsh and humiliated Germany. Article 231 (War Guilt Clause) forced Germany to accept total blame, justifying crushing reparations of £6.6 billion. Germany lost 13% of its European territory, including Alsace-Lorraine and the Polish Corridor, while its military was slashed to 100,000 men with no air force or tanks. German citizens denounced it as a dictated peace ('Diktat') and sought revenge.<br><br>On the other hand, the treaty left Germany fundamentally intact as a major European industrial power. Unlike the Austro-Hungarian and Ottoman empires, which were completely dismantled, Germany retained its industrial heartlands in the Ruhr and Rhineland. Therefore, while its terms created intense political bitterness, the war was caused by the failure of Britain and France to enforce the treaty in the 1930s rather than the treaty terms alone.",
